import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
vehicle_info = []
for rec in capacity_records:
    v = rec['values']
    vehicle_info.append({'VehicleID': int(v['VehicleID']), 'VehicleType': v['VehicleType'], 'Capacity': int(v['Capacity'])})
vehicle_info.sort(key=lambda x: x['VehicleID'])
product_value = {}
for rec in product_records:
    v = rec['values']
    product_value[v['ProductName']] = int(v['Value'])
vehicle_ids = [str(v['VehicleID']) for v in vehicle_info]
vehicle_types = [v['VehicleType'] for v in vehicle_info]
capacities = {v['VehicleType']: v['Capacity'] for v in vehicle_info}
values = {}
for v in vehicle_info:
    vt = v['VehicleType']
    if vt not in product_value:
        raise ValueError(f'Missing Value for vehicle type {vt}')
    values[vt] = product_value[vt]
m = gp.Model('NewCarSalesInNorway')
x_vars = m.addVars(vehicle_types, lb=0, ub=[capacities[vt] for vt in vehicle_types], vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((values[vt] * x_vars[vt] for vt in vehicle_types)), GRB.MAXIMIZE)
total_capacity = sum((capacities[vt] for vt in vehicle_types))
m.addConstr(gp.quicksum((x_vars[vt] for vt in vehicle_types)) <= total_capacity, name='total_capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for vt in vehicle_types:
        print(f'x[{vt}]: {x_vars[vt].X}')
else:
    print(f'Solver status: {m.Status}')